#include <stdio.h>
#include <string.h>

static int cnt[282];

/* Mapeia índice de letra acentuada minúscula (Latin-1: 0xA0..0xBF)
   para a letra base ('a'..'z'); -1 se desconhecida. */
static int folded(int x) {
    if (x >= 0xA0 && x <= 0xA6) return 'a' - 'a';            /* à á â ã ä å æ */
    if (x == 0xA7) return 'c' - 'a';                          /* ç */
    if (x >= 0xA8 && x <= 0xAB) return 'e' - 'a';             /* è é ê ë */
    if (x >= 0xAC && x <= 0xAF) return 'i' - 'a';             /* ì í î ï */
    if (x == 0xB1) return 'n' - 'a';                          /* ñ */
    if ((x >= 0xB2 && x <= 0xB6) || x == 0xB8) return 'o' - 'a'; /* ò ó ô õ ö ø */
    if (x >= 0xB9 && x <= 0xBC) return 'u' - 'a';             /* ù ú û ü */
    if (x == 0xBD || x == 0xBF) return 'y' - 'a';             /* ý ÿ */
    return -1;
}

/* Retorna o id do próximo token, avançando *i. -1 significa '*'.
   Ids: 0..25 = letras; >=26 = outros bytes (mantêm identidade). */
static int nextTok(const unsigned char *s, size_t *i) {
    unsigned char b = s[(*i)++];
    if (b == '*') return -1;
    if (b >= 'a' && b <= 'z') return b - 'a';
    if (b >= 'A' && b <= 'Z') return b - 'A';
    if (b == 0xC3) {                       /* UTF-8 de letras acentuadas latinas */
        unsigned char n = s[*i];
        if (n >= 0x80 && n <= 0xBF) {
            (*i)++;
            int x = (n < 0xA0) ? n + 0x20 : n;
            int L = folded(x);
            return (L >= 0) ? L : 26 + (int)b;
        }
    }
    if (b >= 0xC0) {                       /* Latin-1 acentuado (E0..FF minúsc., C0..DF maiúsc.) */
        int x = (b >= 0xE0) ? (int)b - 0x40 : (int)b - 0x20;
        if (x >= 0xA0 && x <= 0xBF) {
            int L = folded(x);
            if (L >= 0) return L;
        }
    }
    return 26 + (int)b;
}

int main(void) {
    static char P[4096], A[4096];
    const unsigned char *pp, *pa;
    size_t i, j;
    int ok = 1, t;

    if (scanf("%4095s", P) != 1) { puts("N"); return 0; }
    if (scanf("%4095s", A) != 1) { puts("N"); return 0; }

    pp = (const unsigned char *)P;
    if (pp[0] == 0xEF && pp[1] == 0xBB && pp[2] == 0xBF) pp += 3; /* BOM */
    pa = (const unsigned char *)A;

    memset(cnt, 0, sizeof(cnt));

    /* Conta as letras disponíveis em P */
    i = 0;
    while (pp[i]) {
        t = nextTok(pp, &i);
        if (t >= 0) cnt[t]++;
    }

    /* A é anagrama curinga de P (|A| = |P|) sse as letras fixas de A
       formam um submulticonjunto das letras de P; os '*' cobrem o restante. */
    j = 0;
    while (pa[j] && ok) {
        t = nextTok(pa, &j);
        if (t < 0) continue;               /* '*' ignora a letra original */
        if (cnt[t] > 0) cnt[t]--;
        else ok = 0;
    }

    puts(ok ? "S" : "N");
    return 0;
}
